/*
 * Asks for the calendar permission, for the site's Calendar tab: the page links here
 * (main-site/js/calendar.js) when the app says it may not read the calendar yet, as an Android
 * prompt can only come from an app's own screen. Shows nothing but the prompt, then goes back
 * to the page, which asks the app for the events again.
 *
 * Once it's been refused for good ("Don't allow" twice, or "Don't ask again"), Android won't
 * prompt any more, so this opens the app's settings to turn it on there instead.
 *
 * Not generated by Bubblewrap: kept by `bubblewrap update` (see android/README.md).
 */
package org.uwuapps.sgbus;

import android.Manifest;
import android.app.Activity;
import android.content.Intent;
import android.content.SharedPreferences;
import android.net.Uri;
import android.os.Build;
import android.os.Bundle;
import android.provider.Settings;

public class CalendarPermissionActivity extends Activity {
    private static final int REQUEST = 1;
    private static final String PREFS = "calendar_permission";
    private static final String REFUSED_FOR_GOOD = "refused_for_good";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        if (CalendarReader.allowed(this) || Build.VERSION.SDK_INT < Build.VERSION_CODES.M) {
            finish();
            return;
        }
        if (prefs().getBoolean(REFUSED_FOR_GOOD, false)) {
            startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,
                    Uri.fromParts("package", getPackageName(), null)));
            finish();
            return;
        }
        requestPermissions(new String[] {Manifest.permission.READ_CALENDAR}, REQUEST);
    }

    @Override
    public void onRequestPermissionsResult(int requestCode, String[] permissions, int[] results) {
        boolean granted = results.length > 0 && results[0] == android.content.pm.PackageManager.PERMISSION_GRANTED;
        // Refused, and Android no longer offers to ask again: settings is the only way next time.
        boolean forGood = !granted && Build.VERSION.SDK_INT >= Build.VERSION_CODES.M
                && !shouldShowRequestPermissionRationale(Manifest.permission.READ_CALENDAR);
        prefs().edit().putBoolean(REFUSED_FOR_GOOD, forGood).apply();
        finish();
    }

    private SharedPreferences prefs() {
        return getSharedPreferences(PREFS, MODE_PRIVATE);
    }
}
